buggyCode:
public record Order(Long id, Long ownerId) {}
public record CurrentUser(Long id) {}

boolean canCancel(Order order, CurrentUser user) {
    return order.ownerId() == user.id();
}

// Mô phỏng: id đọc từ DB qua JPA, mỗi lần là một object Long riêng
System.out.println(canCancel(new Order(1L, Long.valueOf(42)), new CurrentUser(Long.valueOf(42))));
System.out.println(canCancel(new Order(2L, Long.valueOf(1000)), new CurrentUser(Long.valueOf(1000))));

fix.code:
boolean canCancel(Order order, CurrentUser user) {
    return Objects.equals(order.ownerId(), user.id());
}

// Hoặc dùng primitive khi id không thể null:
public record CurrentUser(long id) {}
// order.ownerId() == user.id() lúc này unboxing vế Long rồi so hai long
